/**
 * tag-fix-guard — #432 TOCTOU regression pin over tag-fix.kit.py (a
 * python corpus kit, so no same-stem TS subject exists — allowlisted in
 * test-placement-census). The standard RB-closed posture tests (shared
 * PY_RB_COMMIT_GUARD fragment, pgrep-last-gate, fail-closed lost race,
 * success-only checkpoint) are generated by describeRbGuard; the pin
 * below adds tag-fix's own mutation-ordering rule.
 */
import { expect, test } from "bun:test";
import { describeRbGuard } from "./test-support/rb-guard-assertions";

describeRbGuard("tag-fix.kit.py", "rb_guarded_commit(rbdb)", ({ lines, callIndexes }) => {
  test("every master.db mutation happens before the guarded commit, none after", () => {
    const callIdx = callIndexes[0] ?? -1;
    const mutation = /c\.(Title|ArtistID|OrgArtistID)\s*=|session\.add\(/u;
    const lastMutation = lines.reduce((acc, l, i) => (mutation.test(l) ? i : acc), -1);
    expect(lastMutation).toBeGreaterThan(-1);
    expect(lastMutation).toBeLessThan(callIdx);
  });
});
